class Solution {
    Node* head(Node* n) { return n->prev ? head(n->prev) : n; }
    void go(Node* n, vector<int>& r) { if (!n) return; r.push_back(n->val); go(n->next, r); }
public:
    vector<int> toArray(Node* node) {
        vector<int> r; go(head(node), r); return r;
    }
};

c.java:
class Solution {
    private Node head(Node n) { return n.prev == null ? n : head(n.prev); }
    private void go(Node n, List<Integer> l) { if (n == null) return; l.add(n.val); go(n.next, l); }
    public int[] toArray(Node node) {
        List<Integer> l = new ArrayList<>(); go(head(node), l);
        return l.stream().mapToInt(Integer::intValue).toArray();
    }
}

